import { INF } from '../../core/types'
import type { Day } from '../../core/types'
import type { IntervalState } from '../../core/strategies/intervals'
import { linear } from '../scale'
import { show } from '../Readout'

const W = 1000
const ROW_H = 20
const PAD = 4

/**
 * Every row this strategy has ever stored, drawn as a rectangle on the same
 * valid-time axis the rest of the interface uses. Open rows (still current in
 * system time) render solid; closed rows fade but stay on screen — the audit
 * trail a retroactive write leaves behind, rather than a mutation that erases
 * it. Rows are never deduplicated: one rectangle per stored row.
 */
export function IntervalRows({
  state, horizon,
}: { state: IntervalState; horizon: { start: Day; end: Day } }) {
  const rows = [...state.rows].sort(
    (a, b) => a.attr.localeCompare(b.attr) || a.validFrom - b.validFrom || a.systemFrom - b.systemFrom,
  )
  if (rows.length === 0) {
    return <div style={{ fontSize: 12, color: 'var(--ink-faint)' }}>no rows</div>
  }

  const x = linear([horizon.start, horizon.end], [PAD, W - PAD])
  const h = rows.length * ROW_H

  return (
    <div style={{ maxHeight: 160, overflowY: 'auto' }}>
      <svg viewBox={`0 0 ${W} ${h}`} width="100%" style={{ display: 'block' }}>
        {rows.map((r, i) => {
          const open = r.systemTo === INF
          const from = Math.min(Math.max(r.validFrom, horizon.start), horizon.end)
          const to = Math.min(r.validTo === INF ? horizon.end : r.validTo, horizon.end)
          const x0 = x(from)
          const x1 = x(Math.max(from, to))
          const y = i * ROW_H
          return (
            <g key={r.id} opacity={open ? 1 : 0.35}>
              <rect x={x0} y={y + 3} width={Math.max(1, x1 - x0)} height={ROW_H - 6}
                    fill="var(--rule-strong)" rx={2} />
              <text x={x0 + 4} y={y + ROW_H - 7} fontSize={10} fill="var(--ink)">
                {r.attr}: {show(r.value)}
              </text>
            </g>
          )
        })}
      </svg>
    </div>
  )
}

import { formatDay } from '../../core/dates'
import { referenceQuery } from '../../core/reference'
import { ATTRS, INF } from '../../core/types'
import type { Day, Fact } from '../../core/types'
import type { Snapshot } from '../../core/strategies/snapshots'
import { show } from '../Readout'

/** The shape shared by snapshots.ts, hybrid.ts and snapshotStale.ts. */
export type SnapshotLikeState = { log: Fact[]; snapshots: Snapshot[]; seq: number }

/**
 * Every snapshot this strategy has ever stored, oldest valid-time first. Open
 * snapshots (still current in system time) render solid; closed ones fade but
 * stay, same convention as IntervalRows.
 *
 * With `checkStale`, an open snapshot whose stored values disagree with the
 * oracle at (its validAt, systemCursor) is marked — that is snapshotStale's
 * bug made visible in the storage itself, not only in the answer it returns.
 */
export function SnapshotStack({
  state, systemCursor, checkStale,
}: { state: SnapshotLikeState; systemCursor: Day; checkStale: boolean }) {
  const snaps = [...state.snapshots].sort(
    (a, b) => a.validAt - b.validAt || a.systemFrom - b.systemFrom,
  )
  if (snaps.length === 0) {
    return <div style={{ fontSize: 12, color: 'var(--ink-faint)' }}>no snapshots</div>
  }

  return (
    <div style={{ maxHeight: 160, overflowY: 'auto' }}>
      <table>
        <thead>
          <tr>
            <th>valid at</th>
            {ATTRS.map((a) => <th key={a}>{a}</th>)}
            <th>system</th>
          </tr>
        </thead>
        <tbody>
          {snaps.map((s) => {
            const open = s.systemTo === INF
            const stale = checkStale && open && ATTRS.some(
              (a) => s.state[a] !== referenceQuery(state.log, a, s.validAt, systemCursor),
            )
            return (
              <tr key={s.id} style={{ opacity: open ? 1 : 0.4 }}>
                <td>
                  {formatDay(s.validAt)}
                  {stale && <span className="tag wrong" style={{ marginLeft: 6 }}>stale</span>}
                </td>
                {ATTRS.map((a) => <td key={a} className="num">{show(s.state[a])}</td>)}
                <td>{formatDay(s.systemFrom)}–{s.systemTo === INF ? '…' : formatDay(s.systemTo)}</td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

import type { ReactNode } from 'react'
import type { Day } from '../../core/types'
import type { DeltaState } from '../../core/strategies/deltas'
import type { IntervalState } from '../../core/strategies/intervals'
import { EventList } from './EventList'
import { IntervalRows } from './IntervalRows'
import { SnapshotStack } from './SnapshotStack'
import type { SnapshotLikeState } from './SnapshotStack'

export type InternalsProps = {
  horizon: { start: Day; end: Day }
  validCursor: Day
  systemCursor: Day
}

/**
 * Picks the renderer for a strategy's own state shape. One entry per key in
 * the registry; an unknown key renders nothing rather than guessing at a
 * shape it was not built to read.
 */
export function renderInternals(key: string, state: unknown, props: InternalsProps): ReactNode {
  switch (key) {
    case 'deltas':
      return <EventList state={state as DeltaState} systemCursor={props.systemCursor} />
    case 'intervals':
      return <IntervalRows state={state as IntervalState} horizon={props.horizon} />
    case 'snapshots':
    case 'hybrid':
      return (
        <SnapshotStack
          state={state as SnapshotLikeState} systemCursor={props.systemCursor} checkStale={false}
        />
      )
    case 'snapshotStale':
      return (
        <SnapshotStack
          state={state as SnapshotLikeState} systemCursor={props.systemCursor} checkStale
        />
      )
    default:
      return null
  }
}

import { formatDay } from '../../core/dates'
import type { Day, Fact } from '../../core/types'
import type { DeltaState } from '../../core/strategies/deltas'
import { show } from '../Readout'

/**
 * The whole append-only log, in stored order. Nothing is derived — the point
 * of this renderer is that there is nothing to derive, only a replay cost paid
 * at read time. Facts not yet recorded at the system cursor are dimmed rather
 * than hidden, matching TwinTimelines.
 */
export function EventList({
  state, systemCursor,
}: { state: DeltaState; systemCursor: Day }) {
  if (state.facts.length === 0) {
    return <div style={{ fontSize: 12, color: 'var(--ink-faint)' }}>no facts</div>
  }

  return (
    <div style={{ maxHeight: 160, overflowY: 'auto' }}>
      <table>
        <thead>
          <tr><th>attr</th><th>value</th><th>valid</th><th>system</th></tr>
        </thead>
        <tbody>
          {state.facts.map((f: Fact) => (
            <tr key={f.id} style={{ opacity: f.systemTime > systemCursor ? 0.35 : 1 }}>
              <td>{f.attr}</td>
              <td className="num">{show(f.value)}</td>
              <td>{formatDay(f.validFrom)}</td>
              <td>{formatDay(f.systemTime)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

import { referenceQuery } from '../core/reference'
import { materialize, NO_OPS } from '../core/strategies/index'
import type { Config } from '../core/strategies/index'
import type { AnyStrategy } from '../core/strategies/registry'
import { ATTRS } from '../core/types'
import type { Day, Fact } from '../core/types'
import { renderInternals } from './internals/index'
import { seriesColour } from './palette'
import { show } from './Readout'

type Props = {
  strategy: AnyStrategy
  log: readonly Fact[]
  config: Config
  validCursor: Day
  systemCursor: Day
  horizon: { start: Day; end: Day }
}

/**
 * One strategy's full answer to the same two questions every other row is
 * asked, plus what it cost and what it is holding onto internally. The
 * disagreement marker is the entire point of the tool, so it is the one thing
 * here allowed to be loud.
 */
export function StrategyRow({ strategy, log, config, validCursor, systemCursor, horizon }: Props) {
  const { state } = materialize(strategy, log, config)

  const lastFact = log.length > 0 ? log[log.length - 1]! : undefined
  const lastOps = lastFact === undefined
    ? NO_OPS
    : strategy.apply(materialize(strategy, log.slice(0, -1), config).state, lastFact, config).ops

  const size = strategy.size(state)

  return (
    <div className="panel" style={{ display: 'grid', gap: 10 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
        <span aria-hidden style={{
          width: 3, minHeight: 34, alignSelf: 'stretch', borderRadius: 2,
          background: seriesColour(strategy.key),
        }} />

        <div style={{ minWidth: 172 }}>
          <div style={{ fontWeight: 600 }}>{strategy.name}</div>
          <div style={{ fontSize: 12, color: 'var(--ink-faint)' }}>{strategy.blurb}</div>
        </div>

        <div style={{ display: 'flex', gap: 20 }}>
          {ATTRS.map((attr) => {
            const got = strategy.query(state, attr, validCursor, systemCursor)
            const oracle = referenceQuery(log, attr, validCursor, systemCursor)
            const agree = got === oracle
            return (
              <div key={attr}>
                <div style={{ fontSize: 11, color: 'var(--ink-faint)' }}>{attr}</div>
                <div className="num" style={{ fontSize: 15, fontWeight: 600 }}>
                  {show(got)}
                  {agree ? (
                    <span style={{ color: 'var(--ok)', marginLeft: 6 }} title="agrees with the oracle">
                      ok
                    </span>
                  ) : (
                    <span className="tag wrong" style={{ marginLeft: 6 }}>oracle {show(oracle)}</span>
                  )}
                </div>
              </div>
            )
          })}
        </div>

        <div style={{ display: 'flex', gap: 16, marginLeft: 'auto', fontSize: 12, color: 'var(--ink-soft)' }}>
          <OpStat label="written" value={lastOps.written} />
          <OpStat label="rewritten" value={lastOps.rewritten} />
          <OpStat label="invalidated" value={lastOps.invalidated} />
          <OpStat label="records" value={size} />
        </div>
      </div>

      <div>{renderInternals(strategy.key, state, { horizon, validCursor, systemCursor })}</div>
    </div>
  )
}

function OpStat({ label, value }: { label: string; value: number }) {
  return (
    <div>
      <div style={{ fontSize: 11, color: 'var(--ink-faint)' }}>{label}</div>
      <div className="num">{value.toLocaleString('en-GB')}</div>
    </div>
  )
}

import { INF } from '../types'
import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

/**
 * A row is a rectangle on the bitemporal plane: a value that held over a range
 * of valid time, believed over a range of system time. Both ends are exclusive,
 * INF meaning still open.
 */
export type Interval = {
  id: string
  attr: Attr
  value: Value
  validFrom: Day
  validTo: Day
  systemFrom: Day
  systemTo: Day
}

export type IntervalState = { rows: Interval[]; seq: number }

const isOpen = (r: Interval) => r.systemTo === INF

/**
 * Validity intervals — the classic bitemporal table.
 *
 * Reads are a direct lookup: find the rectangle containing the coordinate. The
 * price is on write. A retroactive fact does not append, it *rewrites*: every
 * open row it overlaps is closed in system time and reopened with adjusted
 * valid bounds. Nothing is ever mutated in place, so the system-time axis stays
 * an audit trail, but one fact can touch many rows.
 *
 * The subtlety worth reading: the new fact does not run to infinity. It holds
 * only until the next already-known fact supersedes it, so its valid range is
 * clipped at the nearest greater validFrom. Skipping that clip is the classic
 * way to make a retroactive insert silently swallow every later change.
 */
export const intervals: Strategy<IntervalState> = {
  key: 'intervals',
  name: 'Intervals',
  blurb: 'Bitemporal rectangles. Direct reads, rewriting writes.',
  correct: true,

  empty: () => ({ rows: [], seq: 0 }),

  apply(state: IntervalState, fact: Fact, _cfg: Config): Applied<IntervalState> {
    const { attr, value, validFrom: v, systemTime: t } = fact
    let seq = state.seq
    const id = () => `${fact.id}-${++seq}`

    const open = state.rows.filter((r) => r.attr === attr && isOpen(r))

    // The new fact holds until the next thing we already know about.
    let nextValid = INF
    for (const r of open) {
      if (r.validFrom > v && r.validFrom < nextValid) nextValid = r.validFrom
    }

    const rows: Interval[] = []
    let written = 0
    let rewritten = 0

    for (const r of state.rows) {
      const untouched =
        r.attr !== attr || !isOpen(r) || r.validTo <= v || r.validFrom >= nextValid
      if (untouched) {
        rows.push(r)
        continue
      }

      // Close in system time rather than mutating. A zero-width system range can
      // never be read back, so it is dropped rather than stored as noise.
      if (r.systemFrom < t) {
        rows.push({ ...r, systemTo: t })
        rewritten += 1
      } else {
        rewritten += 1
      }

      // Reopen whatever of this row survives on either side of the new fact.
      if (r.validFrom < v) {
        rows.push({ ...r, id: id(), validTo: v, systemFrom: t, systemTo: INF })
        written += 1
      }
      if (r.validTo > nextValid) {
        rows.push({ ...r, id: id(), validFrom: nextValid, systemFrom: t, systemTo: INF })
        written += 1
      }
    }

    rows.push({
      id: id(), attr, value,
      validFrom: v, validTo: nextValid,
      systemFrom: t, systemTo: INF,
    })
    written += 1

    return { state: { rows, seq }, ops: { written, rewritten, invalidated: 0 } }
  },

  query(state: IntervalState, attr: Attr, valid: Day, system: Day): Value | undefined {
    for (const r of state.rows) {
      if (r.attr !== attr) continue
      if (valid < r.validFrom || valid >= r.validTo) continue
      if (system < r.systemFrom || system >= r.systemTo) continue
      return r.value
    }
    return undefined
  },

  readCost: (state: IntervalState, attr: Attr) =>
    state.rows.filter((r) => r.attr === attr).length,
  size: (state: IntervalState) => state.rows.length,
}

import { referenceState } from '../reference'
import { INF } from '../types'
import type { Attr, Day, EntityState, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

/**
 * A snapshot is itself bitemporal: a full-state view at one valid-time point,
 * believed over a range of system time. Retiring one closes it rather than
 * mutating it, same as intervals.ts, so past beliefs stay queryable.
 */
export type Snapshot = {
  id: string
  validAt: Day
  state: EntityState
  systemFrom: Day
  systemTo: Day
}

export type SnapshotState = { log: Fact[]; snapshots: Snapshot[]; seq: number }

/** Greatest validAt at or before `valid`, among snapshots live at `system`. */
export function liveSnapshot(
  snaps: readonly Snapshot[], valid: Day, system: Day,
): Snapshot | undefined {
  let best: Snapshot | undefined
  for (const s of snaps) {
    if (system < s.systemFrom || system >= s.systemTo) continue
    if (s.validAt > valid) continue
    if (best === undefined || s.validAt > best.validAt) best = s
  }
  return best
}

/**
 * One full-state snapshot per distinct validFrom seen in the log. A read is a
 * direct lookup: find the live snapshot with the greatest validAt <= valid and
 * you are done — no replay, ever. The cost moves entirely to the write. Every
 * snapshot is a cached projection of state, so a retroactive fact — one whose
 * validFrom lands before points we already snapshotted — must close and rebuild
 * all of them, because what they say just changed. Points before the fact's
 * validFrom are left alone: nothing that already happened can be altered by
 * something recorded to hold from a later point onward.
 */
export const snapshots: Strategy<SnapshotState> = {
  key: 'snapshots',
  name: 'Snapshots',
  blurb: 'One full-state snapshot per valid-time point seen. Direct reads, rebuilding writes.',
  correct: true,

  empty: () => ({ log: [], snapshots: [], seq: 0 }),

  apply(state: SnapshotState, fact: Fact, _cfg: Config): Applied<SnapshotState> {
    const { validFrom: v, systemTime: t } = fact
    const log = [...state.log, fact]
    let seq = state.seq
    const nextId = () => `${fact.id}-${++seq}`

    let invalidated = 0
    const kept: Snapshot[] = []
    for (const s of state.snapshots) {
      const affected = s.systemTo === INF && s.validAt >= v
      if (!affected) { kept.push(s); continue }
      invalidated += 1
      // A snapshot opened and closed at the same instant can never be read
      // back, so it is dropped rather than stored as noise (see intervals.ts).
      if (s.systemFrom < t) kept.push({ ...s, systemTo: t })
    }

    const points = [...new Set(log.map((f) => f.validFrom))].filter((p) => p >= v)
    let written = 0
    for (const p of points) {
      kept.push({
        id: nextId(), validAt: p, state: referenceState(log, p, t),
        systemFrom: t, systemTo: INF,
      })
      written += 1
    }

    return { state: { log, snapshots: kept, seq }, ops: { written, rewritten: 0, invalidated } }
  },

  query(state: SnapshotState, attr: Attr, valid: Day, system: Day): Value | undefined {
    return liveSnapshot(state.snapshots, valid, system)?.state[attr]
  },

  readCost: (state: SnapshotState, _attr: Attr, valid: Day, system: Day) =>
    liveSnapshot(state.snapshots, valid, system) === undefined ? 0 : 1,

  size: (state: SnapshotState) => state.snapshots.length,
}

import type { Day } from './types'

/** Day 0. All Day values are offsets from here. */
export const EPOCH = Date.UTC(2026, 0, 1)
const MS_PER_DAY = 86_400_000

export function day(year: number, month1: number, dayOfMonth: number): Day {
  return Math.round((Date.UTC(year, month1 - 1, dayOfMonth) - EPOCH) / MS_PER_DAY)
}

export function toDate(d: Day): Date {
  return new Date(EPOCH + d * MS_PER_DAY)
}

/**
 * Fixed rather than Intl, deliberately. Locale data varies by platform and ICU
 * version — en-GB renders September as "Sept" in some builds and "Sep" in
 * others — and an explainer that reads differently on the interviewer's machine
 * than on mine is not worth the convenience.
 */
const MONTHS = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
] as const

/** "15 Jan" — for axes and dense tables. */
export function formatDay(d: Day): string {
  const t = toDate(d)
  return `${t.getUTCDate()} ${MONTHS[t.getUTCMonth()]}`
}

/** "15 Jan 2026" — for headers, where the year earns its space. */
export function formatDayLong(d: Day): string {
  return `${formatDay(d)} ${toDate(d).getUTCFullYear()}`
}

import { renderToStaticMarkup } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import { day } from '../core/dates'
import { HORIZON, SCENARIO } from '../core/log'
import { DEFAULT_CONFIG, materialize } from '../core/strategies/index'
import { CORRECT_STRATEGIES, STRATEGIES, strategyByKey } from '../core/strategies/registry'
import { renderInternals } from './internals/index'
import { StrategyRow } from './StrategyRow'
import type { Fact } from '../core/types'

const noNaN = (markup: string) => {
  expect(markup).not.toMatch(/NaN/)
  expect(markup).not.toMatch(/Infinity/)
}

const VALID = day(2026, 5, 1)
const SYSTEM = day(2026, 6, 10)

const renderRow = (strategy: (typeof STRATEGIES)[number], log: readonly Fact[]) =>
  renderToStaticMarkup(
    <StrategyRow
      strategy={strategy} log={log} config={DEFAULT_CONFIG}
      validCursor={VALID} systemCursor={SYSTEM} horizon={HORIZON}
    />,
  )

/** Pulls the number OpStat rendered next to a given label, e.g. "invalidated". */
function statFor(markup: string, label: string): number {
  const m = markup.match(new RegExp(`${label}</div><div class="num">([\\d,]+)</div>`))
  if (!m) throw new Error(`no stat rendered for "${label}"`)
  return Number(m[1]!.replace(/,/g, ''))
}

describe('StrategyRow renders every strategy', () => {
  it('on the scenario, without throwing and without NaN or Infinity', () => {
    for (const strategy of STRATEGIES) {
      const markup = renderRow(strategy, SCENARIO)
      noNaN(markup)
    }
  })

  it('on an empty log, without throwing', () => {
    for (const strategy of STRATEGIES) {
      const markup = renderRow(strategy, [])
      noNaN(markup)
    }
  })
})

describe('agreement with the oracle', () => {
  it('the four correct strategies show no disagreement marker at 1 May / 10 June', () => {
    for (const strategy of CORRECT_STRATEGIES) {
      const markup = renderRow(strategy, SCENARIO)
      expect(markup).not.toContain('tag wrong')
    }
  })

  it('snapshotStale disagrees at that coordinate, showing both its answer and the oracle\'s', () => {
    const strategy = strategyByKey('snapshotStale')!
    const markup = renderRow(strategy, SCENARIO)
    expect(markup).toContain('tag wrong')
    expect(markup).toContain('60,000')
    expect(markup).toContain('72,000')
  })
})

describe('IntervalRows', () => {
  it('accumulates closed rows rather than mutating them away', () => {
    const strategy = strategyByKey('intervals')!
    const before = materialize(strategy, SCENARIO.slice(0, -1), DEFAULT_CONFIG).state
    const after = materialize(strategy, SCENARIO, DEFAULT_CONFIG).state

    const props = { horizon: HORIZON, validCursor: VALID, systemCursor: SYSTEM }
    const beforeCount = (
      renderToStaticMarkup(<>{renderInternals('intervals', before, props)}</>).match(/<rect/g) ?? []
    ).length
    const afterCount = (
      renderToStaticMarkup(<>{renderInternals('intervals', after, props)}</>).match(/<rect/g) ?? []
    ).length

    expect(afterCount).toBeGreaterThan(beforeCount)
  })
})

describe('last-fact ops', () => {
  // The last SCENARIO fact is the backdated raise: it invalidates cached
  // snapshots but costs deltas nothing beyond the append itself.
  it('snapshots shows a non-zero invalidated count', () => {
    const markup = renderRow(strategyByKey('snapshots')!, SCENARIO)
    expect(statFor(markup, 'invalidated')).toBeGreaterThan(0)
  })

  it('deltas shows a zero invalidated count', () => {
    const markup = renderRow(strategyByKey('deltas')!, SCENARIO)
    expect(statFor(markup, 'invalidated')).toBe(0)
  })
})

